267	func listDeleteUserInboxIDs(ctx context.Context, tx *sql.Tx, userID int32, memoIDSet map[int32]struct{}) ([]int32, error) {
268		directIDs, err := listDeleteUserDirectInboxIDs(ctx, tx, userID)
269		if err != nil {
270			return nil, err
271		}
272		inboxIDs := append([]int32{}, directIDs...)
273		if len(memoIDSet) == 0 {
274			return inboxIDs, nil
275		}
276	
277		memoIDs, err := listDeleteUserMemoReferencedInboxIDs(ctx, tx, userID, memoIDSet)
278		if err != nil {
279			return nil, err
280		}
281		return append(inboxIDs, memoIDs...), nil
282	}
283	
284	func listDeleteUserDirectInboxIDs(ctx context.Context, tx *sql.Tx, userID int32) ([]int32, error) {
285		rows, err := tx.QueryContext(ctx, `
286			SELECT id
287			FROM inbox
288			WHERE sender_id = `+deleteUserPlaceholder(1)+`
289				OR receiver_id = `+deleteUserPlaceholder(2), userID, userID)
290		if err != nil {
291			return nil, err
292		}
293		defer rows.Close()
294	
295		inboxIDs := make([]int32, 0)
296		for rows.Next() {
297			var inboxID int32
298			if err := rows.Scan(&inboxID); err != nil {
299				return nil, err
300			}
301			inboxIDs = append(inboxIDs, inboxID)
302		}
303		if err := rows.Err(); err != nil {
304			return nil, err
305		}
306	
307		return inboxIDs, nil
308	}
309	
310	func listDeleteUserMemoReferencedInboxIDs(ctx context.Context, tx *sql.Tx, userID int32, memoIDSet map[int32]struct{}) ([]int32, error) {
311		rows, err := tx.QueryContext(ctx, `
312			SELECT id, message
313			FROM inbox
314			WHERE sender_id <> `+deleteUserPlaceholder(1)+`
315				AND receiver_id <> `+deleteUserPlaceholder(2), userID, userID)
316		if err != nil {
317			return nil, err
318		}
319		defer rows.Close()
320	
321		inboxIDs := make([]int32, 0)
322		for rows.Next() {
323			var (
324				inboxID    int32
325				messageRaw []byte
326			)
327			if err := rows.Scan(&inboxID, &messageRaw); err != nil {
328				return nil, err
329			}
330			if len(messageRaw) == 0 {
331				continue
332			}
333	
334			message := &storepb.InboxMessage{}
335			if err := protojsonUnmarshaler.Unmarshal(messageRaw, message); err != nil {
336				return nil, err
337			}
338			if inboxMessageTouchesMemoSet(message, memoIDSet) {
339				inboxIDs = append(inboxIDs, inboxID)
340			}
341		}
342		if err := rows.Err(); err != nil {
343			return nil, err
344		}
345	
346		return inboxIDs, nil
347	}
348	
349	func inboxMessageTouchesMemoSet(message *storepb.InboxMessage, memoIDSet map[int32]struct{}) bool {
350		if message == nil {
351			return false
352		}
353	
354		switch message.Type {
355		case storepb.InboxMessage_MEMO_COMMENT:
356			payload := message.GetMemoComment()
357			if payload == nil {
358				return false
359			}
360			return memoIDInSet(payload.MemoId, memoIDSet) || memoIDInSet(payload.RelatedMemoId, memoIDSet)
361		case storepb.InboxMessage_MEMO_MENTION:
362			payload := message.GetMemoMention()
363			if payload == nil {
364				return false
365			}
366			return memoIDInSet(payload.MemoId, memoIDSet) || memoIDInSet(payload.RelatedMemoId, memoIDSet)
367		default:
368			return false
369		}
370	}
371	
372	func memoIDInSet(id int32, memoIDSet map[int32]struct{}) bool {
373		if id == 0 {
374			return false
375		}
376		_, exists := memoIDSet[id]
377		return exists
378	}
379	
380	func deleteReactionsByContentIDsTx(ctx context.Context, tx *sql.Tx, contentIDs []string) error {
381		for _, batch := range deleteUserBatches(contentIDs, deleteUserBatchSize) {
382			clause, args := deleteUserInClause(1, batch)
383			if _, err := tx.ExecContext(ctx, `DELETE FROM reaction WHERE content_id IN `+clause, args...); err != nil {
384				return err
385			}
386		}
387		return nil
388	}
389	
390	func deleteAttachmentsByIDsTx(ctx context.Context, tx *sql.Tx, attachmentIDs []int32) error {
391		for _, batch := range deleteUserBatches(attachmentIDs, deleteUserBatchSize) {
392			clause, args := deleteUserInClause(1, batch)
393			if _, err := tx.ExecContext(ctx, `DELETE FROM attachment WHERE id IN `+clause, args...); err != nil {
394				return err
395			}
396		}
397		return nil
398	}
399	
400	func deleteReactionsByCreatorTx(ctx context.Context, tx *sql.Tx, userID int32) error {
401		_, err := tx.ExecContext(ctx, `DELETE FROM reaction WHERE creator_id = `+deleteUserPlaceholder(1), userID)
402		return err
403	}
404	
405	func deleteMemoSharesTx(ctx context.Context, tx *sql.Tx, userID int32, memoIDs []int32) error {
406		if _, err := tx.ExecContext(ctx, `DELETE FROM memo_share WHERE creator_id = `+deleteUserPlaceholder(1), userID); err != nil {
407			return err
408		}
409		for _, batch := range deleteUserBatches(memoIDs, deleteUserBatchSize) {
410			clause, args := deleteUserInClause(1, batch)
411			if _, err := tx.ExecContext(ctx, `DELETE FROM memo_share WHERE memo_id IN `+clause, args...); err != nil {
412				return err
413			}
414		}
415		return nil
416	}
417	
418	func deleteInboxesByIDsTx(ctx context.Context, tx *sql.Tx, inboxIDs []int32) error {
419		for _, batch := range deleteUserBatches(inboxIDs, deleteUserBatchSize) {
420			clause, args := deleteUserInClause(1, batch)
421			if _, err := tx.ExecContext(ctx, `DELETE FROM inbox WHERE id IN `+clause, args...); err != nil {
422				return err
423			}
424		}
425		return nil
426	}
427	
428	func deleteUserIdentitiesTx(ctx context.Context, tx *sql.Tx, userID int32) error {
429		_, err := tx.ExecContext(ctx, `DELETE FROM user_identity WHERE user_id = `+deleteUserPlaceholder(1), userID)
430		return err
431	}
432	
433	func deleteUserSettingsTx(ctx context.Context, tx *sql.Tx, userID int32) error {
434		_, err := tx.ExecContext(ctx, `DELETE FROM user_setting WHERE user_id = `+deleteUserPlaceholder(1), userID)
435		return err
436	}
437	
438	func deleteMemoRelationsTx(ctx context.Context, tx *sql.Tx, memoIDs []int32) error {
439		for _, batch := range deleteUserBatches(memoIDs, deleteUserBatchSize) {
440			memoClause, args := deleteUserInClause(1, batch)
441			relatedClause, relatedArgs := deleteUserInClause(len(args)+1, batch)
442			query := `DELETE FROM memo_relation WHERE memo_id IN ` + memoClause + ` OR related_memo_id IN ` + relatedClause
443			args = append(args, relatedArgs...)
444			if _, err := tx.ExecContext(ctx, query, args...); err != nil {
445				return err
446			}
447		}
448		return nil
449	}
450	
451	func deleteMemosTx(ctx context.Context, tx *sql.Tx, memoIDs []int32) error {
452		for _, batch := range deleteUserBatches(memoIDs, deleteUserBatchSize) {
453			clause, args := deleteUserInClause(1, batch)
454			if _, err := tx.ExecContext(ctx, `DELETE FROM memo WHERE id IN `+clause, args...); err != nil {
455				return err
456			}
457		}
458		return nil
459	}
460	
461	func deleteUserRowTx(ctx context.Context, tx *sql.Tx, userID int32) error {
462		_, err := tx.ExecContext(ctx, `DELETE FROM user WHERE id = `+deleteUserPlaceholder(1), userID)
463		return err
464	}
465	
466	func deleteUserPlaceholder(_ int) string {
467		return "?"
468	}
469	
470	func deleteUserInClause[T any](start int, values []T) (string, []any) {
471		placeholders := make([]string, 0, len(values))
472		args := make([]any, 0, len(values))
473		for i, value := range values {
474			placeholders = append(placeholders, deleteUserPlaceholder(start+i))
475			args = append(args, value)
476		}
477		return "(" + strings.Join(placeholders, ", ") + ")", args
478	}
479	
480	func deleteUserBatches[T any](values []T, size int) [][]T {
481		if len(values) == 0 {
482			return nil
483		}
484		if size <= 0 {
485			size = len(values)
486		}
487	
488		batches := make([][]T, 0, (len(values)+size-1)/size)
489		for start := 0; start < len(values); start += size {
490			end := min(start+size, len(values))
491			batches = append(batches, values[start:end])
492		}
493		return batches
494	}
495	
496	func memoIDsFromRefs(memos []deleteUserMemoRef) []int32 {
497		ids := make([]int32, 0, len(memos))
498		for _, memo := range memos {
499			ids = append(ids, memo.ID)
500		}
501		return ids
502	}
503	
504	func memoIDSetFromRefs(memos []deleteUserMemoRef) map[int32]struct{} {
505		idSet := make(map[int32]struct{}, len(memos))
506		for _, memo := range memos {
507			idSet[memo.ID] = struct{}{}
508		}
509		return idSet
510	}
511	
512	func memoContentIDsFromRefs(memos []deleteUserMemoRef) []string {
513		contentIDs := make([]string, 0, len(memos))
514		for _, memo := range memos {
515			contentIDs = append(contentIDs, "memos/"+memo.UID)
516		}
517		return contentIDs
518	}
519	
520	func attachmentIDsFromList(attachments []*store.Attachment) []int32 {
521		ids := make([]int32, 0, len(attachments))
522		for _, attachment := range attachments {
523			if attachment == nil {
524				continue
525			}
526			ids = append(ids, attachment.ID)
527		}
528		return ids
529	}
